using System.Data;
using System.Text.Json;
using System.Security.Cryptography;
using System.Text;
using Dapper;
using Intranet.Entity;
namespace Intranet.Data;
public sealed class QualityEventRepository(GestionConnectionFactory factory):IQualityEventRepository {
 const string Reader="dbo.PA_TI_CC_EVENTOS_S0001";
 static Dictionary<string,object?> Row(object r)=>((IDictionary<string,object>)r).ToDictionary(x=>x.Key.ToLowerInvariant(),x=>x.Value is string s?(object?)s.Trim():x.Value is DBNull?null:x.Value);
 static string Version(Dictionary<string,object?> r)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new[]{"cod_ordtra","num_secuencia","cod_evento_cc","num_secuencia_cc","flg_status_cc","kilos","observaciones","cod_motivo_cc","flg_error_forzado_area","flg_despachado","nro_desviacion","nro_causa"}.Select(k=>Convert.ToString(r.GetValueOrDefault(k))?.Trim()??"")))));
 public async Task<IReadOnlyList<Dictionary<string,object?>>> Search(QualityEventFilter f,CancellationToken ct,bool unfinished=false){await using var c=await factory.OpenAsync(ct);var rows=await c.QueryAsync(new CommandDefinition(unfinished?"dbo.ti_muestra_TI_ORDTRA_TINTORERIA_ITEMS_CC_POR_ACABAR":"dbo.ti_muestra_ti_ordtra_tintoreria_items_cc",new {FEC_EVENTO=f.From.Date,COD_EVENTO_CC=f.EventCode,OPCION=f.Mode.ToString(),COD_ORDTRA=f.Batch.ToUpperInvariant(),FEC_EVENTO_FIN=f.To.Date},commandType:CommandType.StoredProcedure,commandTimeout:90,cancellationToken:ct));return rows.Select(x=>{var row=Row((object)x);row["version"]=Version(row);return row;}).ToList();}
 public async Task<QualityEventBatch> Items(string batch,CancellationToken ct){await using var c=await factory.OpenAsync(ct);QualityEventCustomer? customer;try{customer=await c.QuerySingleOrDefaultAsync<QualityEventCustomer>(new CommandDefinition(Reader,new{MODO="P",COD_ORDTRA=batch.ToUpperInvariant()},commandType:CommandType.StoredProcedure,cancellationToken:ct));}catch(Microsoft.Data.SqlClient.SqlException e)when(e.Number==50000||e.Number==2812){throw new QualityEventConflict("Actualiza PA_TI_CC_EVENTOS_S0001 con el archivo PA_TI_CC_EVENTOS_S0001_Actualizar.sql para consultar el cliente.");}var rows=await c.QueryAsync(new CommandDefinition("dbo.ti_muestra_ti_ordtra_tintoreria_items_para_agregar_evento",new{COD_ORDTRA=batch.ToUpperInvariant()},commandType:CommandType.StoredProcedure,cancellationToken:ct));return new(customer,rows.Select(x=>Row((object)x)).ToList());}
 public async Task<IReadOnlyList<DyeingCatalogOption>> Catalogs(CancellationToken ct){await using var c=await factory.OpenAsync(ct);try{using var multi=await c.QueryMultipleAsync(new CommandDefinition(Reader,new{MODO="C"},commandType:CommandType.StoredProcedure,cancellationToken:ct));var all=new List<DyeingCatalogOption>();while(!multi.IsConsumed)all.AddRange(await multi.ReadAsync<DyeingCatalogOption>());return all;}catch(Microsoft.Data.SqlClient.SqlException e)when(e.Number==2812){throw new QualityEventConflict("Falta crear PA_TI_CC_EVENTOS_S0001.sql en HIALPESA.");}}
 public async Task Save(QualityEventUpdate r,CancellationToken ct,bool unfinished=false){await using var c=await factory.OpenAsync(ct);using var tx=c.BeginTransaction(IsolationLevel.Serializable);try{
 foreach(var item in r.Items.OrderBy(i=>i.Sequence)){
 var records=(await c.QueryAsync(new CommandDefinition(unfinished?"dbo.PA_TI_ORDTRA_TINTORERIA_ITEMS_CC_POR_ACABAR_S0001":Reader,new{MODO="L",COD_ORDTRA=r.Batch.ToUpperInvariant(),NUM_SECUENCIA=item.Sequence,COD_EVENTO_CC=r.EventCode},transaction:tx,commandType:CommandType.StoredProcedure,cancellationToken:ct))).Select(x=>Row((object)x)).ToList();
 var current=records.FirstOrDefault(x=>Convert.ToInt32(x["num_secuencia_cc"])==r.EventSequence);
 if(r.Action!="I"&&current is null)throw new QualityEventConflict("El evento ya no existe. Actualiza el listado.");
 if(r.Action!="I"&&(string.IsNullOrEmpty(r.ExpectedVersion)||r.ExpectedVersion!=Version(current!)))throw new QualityEventConflict("El evento cambió desde que lo abriste. Actualiza el listado.");
 if(!r.ConfirmApproved&&((r.Action=="I"&&records.Any(x=>Convert.ToString(x["flg_status_cc"])=="A"))||(r.Action!="I"&&Convert.ToString(current!["flg_status_cc"])=="A"&&(r.Action=="D"||r.Status!="A"))))throw new QualityEventConflict("El evento está aprobado. Confirma la operación para continuar.");
 var p=new DynamicParameters();p.Add("ACCION",r.Action);p.Add("COD_ORDTRA",r.Batch.ToUpperInvariant());p.Add("NUM_SECUENCIA",item.Sequence);p.Add("COD_EVENTO_CC",r.EventCode);p.Add("NUM_SECUENCIA_CC",r.EventSequence);p.Add("FEC_EVENTO",r.Date.Date);p.Add("KILOS",item.Kilos);p.Add("FLG_STATUS_CC",r.Status);p.Add("OBSERVACIONES",r.Observations);p.Add("TIP_AUDITOR",r.Auditor[..1]);p.Add("COD_AUDITOR",r.Auditor[1..]);p.Add("FLG_ERROR_FORZADO_AREA",r.ForcedError?"S":"N");p.Add("COD_MOTIVO_CC",r.Reason);p.Add("RESULTADO_AUDITORIA_EXTERNA",r.ExternalResult);p.Add("COD_UBICACION_REPROCESO",r.Location);p.Add("OBSERVACION_PRODUCCION",r.ProductionObservations);p.Add("FLG_DESPACHADO",r.Dispatched?"S":"N");p.Add("Nro_Desviacion",r.Deviation);p.Add("Nro_Causa",r.Cause);
 await c.ExecuteAsync(new CommandDefinition(unfinished?"dbo.ti_up_man_ti_ordtra_tintoreria_items_cc_Por_Acabar":"dbo.ti_up_man_ti_ordtra_tintoreria_items_cc",p,transaction:tx,commandType:CommandType.StoredProcedure,commandTimeout:90,cancellationToken:ct));
 }tx.Commit();}catch(Microsoft.Data.SqlClient.SqlException e)when(unfinished&&e.Number==2812){try{tx.Rollback();}catch(InvalidOperationException){}throw new QualityEventConflict("Falta crear PA_TI_ORDTRA_TINTORERIA_ITEMS_CC_POR_ACABAR_S0001.sql en HIALPESA.");}catch{try{tx.Rollback();}catch(InvalidOperationException){}throw;}}
}
